package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class MeetingHealthDialog {
 static void show(MainActivity owner){LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(24,12,24,12);TextView status=new TextView(owner);box.addView(status);Button refresh=new Button(owner);refresh.setText("録音進捗を更新");box.addView(refresh);Button mark=new Button(owner);mark.setText("録音中のここ重要を保存");mark.setOnClickListener(v->{try{JSONObject state=MeetingControl.status(owner).getJSONObject("state");MeetingControl.queue(owner,new JSONObject().put("requestId",java.util.UUID.randomUUID().toString()).put("action","mark").put("mode",0).put("sessionId",state.optString("sessionId")).put("label","ここ重要"));status.setText("しおりの保存待ちです。状態を更新して結果を確認してください");}catch(Exception e){status.setText("録音の開始状態を確認できません。接続・進捗を確認してください");}});box.addView(mark);LinearLayout list=new LinearLayout(owner);list.setOrientation(1);box.addView(list);ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("録音の進捗・保存確認").setView(scroll).setPositiveButton("閉じる",null).create();Runnable update=()->{try{JSONObject s=MeetingControl.status(owner).getJSONObject("state"),p=s.optJSONObject("progress");status.setText((s.optBoolean("connected")?s.optString("status"):"グラス未接続・状態が古い可能性があります")+(p==null?"":"\n取得 "+p.optLong("capturedMs")/1000+"秒 / 書込 "+p.optLong("writtenMs")/1000+"秒 / 確定 "+p.optLong("sealedMs")/1000+"秒"));}catch(Exception e){status.setText("進捗を取得できません");}};refresh.setOnClickListener(v->update.run());dialog.show();update.run();new Thread(()->{try{JSONArray rows=MeetingAudioStore.list(owner);owner.runOnUiThread(()->{if(!dialog.isShowing())return;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);Button verify=new Button(owner);verify.setText(new java.util.Date(row.optLong("startedAt"))+" / "+row.optLong("durationMs")/1000+"秒：保存区間を検証");verify.setOnClickListener(v->{verify.setEnabled(false);new Thread(()->{String result;try{result=MeetingAudioStore.verify(owner,row.optString("id")).optString("message");}catch(Exception e){result="検証できません。元のグラス録音を保持してください";}final String message=result;owner.runOnUiThread(()->{if(dialog.isShowing()){verify.setText(message);verify.setEnabled(true);}});},"MeetingVerify").start();});list.addView(verify);Button review=new Button(owner);review.setText("元の録音・しおり・文字起こしを開く");review.setOnClickListener(v->MeetingReviewDialog.show(owner,row.optString("id")));list.addView(review);if(!row.optString("summary").isEmpty()){Button tasks=new Button(owner);tasks.setText("この会議の要約から保留案件を作る");tasks.setOnClickListener(v->MeetingActionsDialog.show(owner,row.optString("id")));list.addView(tasks);}}});}catch(Exception e){owner.runOnUiThread(()->{if(dialog.isShowing())status.setText("記録一覧を取得できません");});}},"MeetingList").start();}
 private MeetingHealthDialog(){}
}
